data_field:
struct S{n:i64}
struct H{s:S}
recursive fn read(p:S)->i64{p.n++;return p.n;}
fn main(){var rows:H[]=[H{s:S{n:7}}];assert(read(rows[0].s)==8);assert(rows[0].s.n==7);print("data_field");}

reference_source:
struct S{n:i64}
var value:S=S{n:7};recursive fn source()->S&{return &value;}
recursive fn read(p:S)->i64{p.n++;return p.n;}
fn main(){assert(read(copy(source()))==8);assert(value.n==7);print("reference_source");}

global_init:
struct S{n:i64}
recursive fn read(p:S)->i64{return p.n;}
var result:i64=read(S{n:7});
fn main(){assert(result==7);print("global_init");}

later_return:
struct S{n:i64}
var value:S=S{n:1};recursive fn use(p:S,x:i64)->i64{return p.n+x;}
recursive fn run(early:bool)->i64{return use(value,{if early{return 7;}3});}
fn main(){assert(run(true)==7);assert(run(false)==4);assert(value.n==1);print("later_return");}

callee_defer:
struct S{n:i64}
recursive fn read(p:S)->i64{defer{p.n=9;assert(p.n==9);}return p.n;}
fn main(){var s:S=S{n:2};assert(read(s)==2);assert(s.n==2);print("callee_defer");}

nested_array:
struct S{mark:u8,values:u16[..3]}
recursive fn read(p:S)->i64{p.values[0]=9;return p.mark+p.values[0]+p.values.len;}
fn main(){var s:S=S{mark:7,values:[1,2]};assert(read(s)==18);assert(s.values[0]==1);assert(s.values.len==2);print("nested_array");}

large:
struct S{bytes:u8[70000],n:i64}
recursive fn read(p:S)->i64{p.bytes[69999]=11;return p.n+p.bytes[69999];}
fn main(){var s:S=S{bytes:default<u8[70000]>(),n:7};assert(read(s)==18);assert(s.bytes[69999]==0);print("large");}

reference_result:
struct S{link:i64&}
recursive fn get(p:S)->i64&{return p.link;}
fn main(){var data:i64[]=[7];var s:S=S{link:data[0]};var link:i64&=get(s);link=9;assert(data[0]==9);assert(link .== &data[0]);print("reference_result");}
